import React, { useEffect, useState } from 'react';
import Modal from "../../Templates/Modal/Modal";
import axios from "axios";
import './Role.css'

function Role({modalActiveRole,setModalActiveRole,updateNominationStatus}) {
    const [roles, setRoles] = useState([]);
    const [checkedItems, setCheckedItems] = useState({});
    const [check, setCheck] = useState();
    const [user, setUser] = useState([])


    useEffect(() => {
    const fetchData = async () => {
        try {
            const resRoles = await axios.get('/api/roles/');
            const rolesData = resRoles.data[0].get_roles;
            setRoles(rolesData);


        } catch (error) {
            console.error('Error fetching data:', error);
        }
    };

    fetchData()

}, [])

    const inputClick = (event, voteId) => {
        const {id, checked} = event.target
        if (checked) {
            setCheckedItems(checked)
        } else {
            setCheckedItems(null)
        }
        setCheck(event.target.value)

        setCheckedItems(prevState => ({
            ...prevState,
            [id]: checked,
        }))
        updateNominationStatus(id)
        setUser(prevState => ({
                ...prevState,
                nomination_status: checked ? voteId : null
            }
        ))
    }



    return (
        <Modal active={modalActiveRole} setActive={setModalActiveRole}>
            <h1>Назначить роль:</h1>
            <hr/>
            <div>
                <div className='voteContainer'>
                    {roles.map((role, id) => (
                        <div key={id} className="voteItem">
                            <label key={id} htmlFor={role.id} className="inputVote">
                                <input
                                    type='checkbox'
                                    id={role.id}
                                    value={role.id}
                                    onChange={(e) => inputClick(e, role.id)}
                                />
                                {role.name}
                            </label>
                        </div>
                    ))}
                </div>
            </div>
        </Modal>
    );
}

export default Role;
